-- Upgrade bank konten. Generator menambahkan konten awal ke content-management.sql.
begin;
create table if not exists public.learning_versions (
  id uuid primary key default gen_random_uuid(),
  data jsonb not null,
  edited_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now()
);
create table if not exists public.learning_current (
  id integer primary key check(id=1),
  revision uuid not null references public.learning_versions(id)
);
create table if not exists public.essay_submissions (
  id uuid primary key,
  student_id uuid not null references public.profiles(id) on delete cascade,
  revision uuid not null references public.learning_versions(id),
  answers jsonb not null,
  created_at timestamptz not null default now()
);
alter table public.learning_versions enable row level security;
alter table public.learning_current enable row level security;
alter table public.essay_submissions enable row level security;
revoke all on public.learning_versions,public.learning_current,public.essay_submissions from anon,authenticated;
grant select on public.essay_submissions to authenticated;
grant all on public.learning_versions,public.learning_current,public.essay_submissions to service_role;
drop policy if exists essay_read on public.essay_submissions;
create policy essay_read on public.essay_submissions for select to authenticated
using (student_id=auth.uid() or public.current_role()='admin' or (public.current_role()='guru' and public.teaches(student_id)));

create or replace function public.get_learning_content() returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
  if coalesce(public.current_role(),'') not in ('admin','guru','murid') then raise exception 'Silakan masuk terlebih dahulu.'; end if;
  return (select jsonb_build_object('id',v.id,'data',v.data) from public.learning_versions v join public.learning_current c on c.revision=v.id where c.id=1);
end; $$;

create or replace function public.validate_learning_item(kind text,item jsonb) returns void
language plpgsql set search_path='' as $$
declare field text; required_fields text[]; img text;
begin
  if item is null or jsonb_typeof(item)<>'object' or octet_length(item::text)>50000 then raise exception 'Isi konten tidak valid atau terlalu panjang.'; end if;
  required_fields:=case kind
    when 'questions' then array['q']
    when 'essays' then array['q']
    when 'materials' then array['title','body']
    when 'ads' then array['title','icon','line','type','reason']
    when 'puzzles' then array['title','image','type','reason','aim','wrongAim','thirdQuestion','thirdCorrect','thirdWrong','thirdExplanation']
    else null end;
  if required_fields is null then raise exception 'Kategori tidak valid.'; end if;
  foreach field in array required_fields loop
    if jsonb_typeof(item->field) is distinct from 'string' or length(trim(item->>field))=0 or length(item->>field)>(case when field='body' then 20000 else 4000 end) then
      raise exception 'Lengkapi kolom % (maksimal % karakter).',field,(case when field='body' then 20000 else 4000 end);
    end if;
  end loop;
  if kind in ('ads','puzzles') and item->>'type' not in ('komersial','nonkomersial') then raise exception 'Jenis iklan tidak valid.'; end if;
  if kind='questions' then
    if jsonb_typeof(item->'o') is distinct from 'array' then raise exception 'Isi empat pilihan jawaban.'; end if;
    if jsonb_array_length(item->'o')<>4 or exists(select 1 from jsonb_array_elements(item->'o') x where jsonb_typeof(x)<>'string' or length(trim(x#>>'{}'))=0 or length(x#>>'{}')>4000) then raise exception 'Isi empat pilihan jawaban.'; end if;
    if not coalesce(item->'a' in ('0'::jsonb,'1'::jsonb,'2'::jsonb,'3'::jsonb),false) then raise exception 'Pilih jawaban benar.'; end if;
  end if;
  foreach field in array array['explanation','guidance'] loop
    if item ? field and (jsonb_typeof(item->field)<>'string' or length(item->>field)>4000) then raise exception 'Petunjuk/pembahasan tidak valid.'; end if;
  end loop;
  if kind in ('materials','puzzles') then
    img:=coalesce(item->>'image','');
    if length(img)>2000 or (img<>'' and img !~ '^(https://[A-Za-z0-9][A-Za-z0-9./_%?=&#:+~-]*|/?[A-Za-z0-9][A-Za-z0-9._/-]*)$') then raise exception 'Gunakan URL gambar HTTPS yang valid.'; end if;
  end if;
end; $$;

create or replace function public.save_learning_item(content_kind text,item_index integer,item_data jsonb,expected_revision uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare current_id uuid; new_id uuid; bank jsonb; items jsonb;
begin
  if coalesce(public.current_role(),'') not in ('admin','guru') then raise exception 'Hanya admin dan guru dapat mengubah konten.'; end if;
  perform public.validate_learning_item(content_kind,item_data);
  select revision into current_id from public.learning_current where id=1 for update;
  if current_id is null then raise exception 'Bank konten belum dipasang.'; end if;
  if current_id is distinct from expected_revision then raise exception 'Konten sudah diubah pengajar lain. Salin perubahan Anda, tutup formulir, lalu klik Muat ulang sebelum mengedit kembali.'; end if;
  select data into bank from public.learning_versions where id=current_id;
  items:=bank->content_kind;
  if item_index is null then
    if jsonb_array_length(items)>=1000 then raise exception 'Maksimal 1000 konten per kategori.'; end if;
    items:=items||jsonb_build_array(item_data);
  else
    if item_index<0 or item_index>=jsonb_array_length(items) then raise exception 'Konten tidak ditemukan.'; end if;
    items:=jsonb_set(items,array[item_index::text],item_data,false);
  end if;
  if content_kind='ads' and ((select count(*) from jsonb_array_elements(items) x where x->>'type'='komersial')<10 or (select count(*) from jsonb_array_elements(items) x where x->>'type'='nonkomersial')<10) then raise exception 'Sediakan minimal 10 iklan komersial dan 10 nonkomersial.'; end if;
  bank:=jsonb_set(bank,array[content_kind],items,false);
  insert into public.learning_versions(data,edited_by) values(bank,auth.uid()) returning id into new_id;
  update public.learning_current set revision=new_id where id=1;
  return jsonb_build_object('id',new_id,'data',bank);
end; $$;

create or replace function public.record_content_attempt(event_id uuid,activity text,correct_count integer,total_count integer,submitted_answers jsonb,content_revision uuid) returns void
language plpgsql security definer set search_path='' as $$
declare bank jsonb; count_items integer;
begin
  if public.current_role() is distinct from 'murid' then raise exception 'Hanya murid dapat menyimpan hasil.'; end if;
  select data into bank from public.learning_versions where id=content_revision;
  if bank is null then raise exception 'Versi konten tidak ditemukan. Masuk kembali untuk memuat konten.'; end if;
  if activity is null or activity not in ('soal','materi','game','puzzle') then raise exception 'Kegiatan tidak valid.'; end if;
  if activity='soal' then
    count_items:=jsonb_array_length(bank->'questions');
    if submitted_answers is null or jsonb_typeof(submitted_answers)<>'array' then raise exception 'Jawaban tidak valid.'; end if;
    if jsonb_array_length(submitted_answers)<>count_items or exists(select 1 from jsonb_array_elements(submitted_answers) x where x not in ('0'::jsonb,'1'::jsonb,'2'::jsonb,'3'::jsonb)) then raise exception 'Jawaban belum lengkap.'; end if;
    select count(*) into correct_count from jsonb_array_elements(submitted_answers) with ordinality x(value,n) where x.value=bank->'questions'->(x.n::int-1)->'a';
    total_count:=count_items;
  end if;
  if correct_count is null or total_count is null or total_count<1 or total_count>1000 or correct_count<0 or correct_count>total_count then raise exception 'Hasil tidak valid.'; end if;
  if activity='materi' and (total_count<>jsonb_array_length(bank->'materials') or correct_count<>total_count) then raise exception 'Materi belum lengkap.'; end if;
  if activity='game' and total_count<>20 then raise exception 'Selesaikan 20 kartu.'; end if;
  if activity='puzzle' and total_count<>3 then raise exception 'Selesaikan tiga pertanyaan analisis.'; end if;
  insert into public.attempts(id,student_id,activity,correct,total) values(event_id,auth.uid(),activity,correct_count,total_count) on conflict(id) do nothing;
end; $$;

create or replace function public.submit_learning_essay(event_id uuid,content_revision uuid,responses jsonb) returns void
language plpgsql security definer set search_path='' as $$
declare bank jsonb; canonical jsonb;
begin
  if public.current_role() is distinct from 'murid' then raise exception 'Hanya murid dapat mengirim jawaban.'; end if;
  select data into bank from public.learning_versions where id=content_revision;
  if bank is null then raise exception 'Versi konten tidak ditemukan.'; end if;
  if responses is null or jsonb_typeof(responses)<>'array' then raise exception 'Jawaban tidak valid.'; end if;
  if jsonb_array_length(responses)=0 or jsonb_array_length(responses)<>jsonb_array_length(bank->'essays') then raise exception 'Lengkapi semua jawaban esai.'; end if;
  if exists(select 1 from jsonb_array_elements(responses) x where jsonb_typeof(x->'answer') is distinct from 'string' or length(trim(x->>'answer'))=0 or length(x->>'answer')>10000) then raise exception 'Jawaban harus berisi 1–10000 karakter.'; end if;
  select jsonb_agg(jsonb_build_object('q',bank->'essays'->(x.n::int-1)->>'q','answer',trim(x.value->>'answer')) order by x.n) into canonical from jsonb_array_elements(responses) with ordinality x(value,n);
  insert into public.essay_submissions(id,student_id,revision,answers) values(event_id,auth.uid(),content_revision,canonical) on conflict(id) do nothing;
end; $$;

revoke all on function public.get_learning_content(),public.validate_learning_item(text,jsonb),public.save_learning_item(text,integer,jsonb,uuid),public.record_content_attempt(uuid,text,integer,integer,jsonb,uuid),public.submit_learning_essay(uuid,uuid,jsonb) from public,anon;
grant execute on function public.get_learning_content(),public.save_learning_item(text,integer,jsonb,uuid),public.record_content_attempt(uuid,text,integer,integer,jsonb,uuid),public.submit_learning_essay(uuid,uuid,jsonb) to authenticated;

-- Storage tersedia di Supabase; blok ini dilewati hanya pada pengujian PostgreSQL lokal.
do $$ begin
  if to_regclass('storage.buckets') is not null then
    insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
      values('learning-images','learning-images',true,5242880,array['image/jpeg','image/png','image/webp'])
      on conflict(id) do update set public=true,file_size_limit=5242880,allowed_mime_types=array['image/jpeg','image/png','image/webp'];
    execute 'drop policy if exists learning_images_insert on storage.objects';
    execute 'create policy learning_images_insert on storage.objects for insert to authenticated with check (bucket_id=''learning-images'' and public.current_role() in (''admin'',''guru''))';
  end if;
end $$;
-- Konten awal hanya dipasang jika bank belum ada; jalankan ulang tanpa menimpa edit pengajar.
do $seed$ declare version_id uuid; begin
  perform pg_advisory_xact_lock(20261010);
  if not exists(select 1 from public.learning_current where id=1) then
    insert into public.learning_versions(data) values('{"questions":[{"q":"Iklan adalah ....","o":["tulisan yang berisi cerita pengalaman seseorang","pesan yang bertujuan menawarkan, memperkenalkan, atau mengajak masyarakat terhadap suatu barang, jasa, atau gagasan","tulisan yang berisi langkah-langkah melakukan sesuatu","teks yang menceritakan suatu peristiwa secara kronologis"],"a":1},{"q":"Tujuan utama sebuah iklan adalah ....","o":["menghibur pembaca dengan cerita menarik","menjelaskan suatu peristiwa secara rinci","memberikan informasi sekaligus memengaruhi khalayak agar tertarik terhadap sesuatu yang ditawarkan atau disampaikan","menyampaikan pengalaman pribadi pembuat iklan"],"a":2},{"q":"Perhatikan teks berikut!\n“Segarkan harimu dengan Fresh Tea! Nikmati rasa teh yang menyegarkan. Beli sekarang dan rasakan kesegarannya!”\nCiri iklan yang paling terlihat pada teks tersebut adalah ....","o":["menggunakan bahasa yang panjang dan rinci","menggunakan bahasa persuasif untuk memengaruhi pembaca","menggunakan alur cerita yang kompleks","menggunakan bahasa ilmiah"],"a":1},{"q":"Berikut yang bukan merupakan ciri-ciri iklan adalah ....","o":["menggunakan bahasa yang menarik","bersifat persuasif","menyampaikan informasi secara jelas","menggunakan penjelasan yang sangat panjang dan berbelit-belit"],"a":3},{"q":"Kalimat yang paling sesuai digunakan dalam sebuah iklan adalah ....","o":["Kemarin saya pergi ke pasar bersama ibu.","Pada suatu hari, hiduplah seorang anak di sebuah desa.","Ayo, gunakan produk ramah lingkungan untuk kehidupan yang lebih baik!","Setelah itu, tokoh tersebut pergi meninggalkan rumahnya."],"a":2},{"q":"Iklan komersial adalah iklan yang ....","o":["bertujuan memperoleh keuntungan melalui penawaran barang atau jasa","hanya berisi cerita hiburan","bertujuan menyampaikan pengalaman pribadi","berisi larangan tanpa tujuan tertentu"],"a":0},{"q":"Perhatikan iklan berikut!\n“Nikmati kelezatan Roti Ceria! Dibuat dari bahan berkualitas dengan rasa yang lezat. Dapatkan sekarang di toko terdekat!”\nIklan tersebut termasuk ....","o":["iklan nonkomersial","iklan layanan masyarakat","iklan komersial","iklan pendidikan"],"a":2},{"q":"Perhatikan iklan berikut!\n“Jangan buang sampah sembarangan! Mari jaga kebersihan lingkungan agar tetap sehat dan nyaman.”\nIklan tersebut termasuk iklan ....","o":["komersial","nonkomersial","perdagangan","produk makanan"],"a":1},{"q":"Perbedaan utama iklan komersial dan nonkomersial terletak pada ....","o":["ukuran tulisan","warna iklan","tujuan dan pesan yang disampaikan","jumlah kata dalam iklan"],"a":2},{"q":"Manakah contoh pesan iklan nonkomersial?","o":["“Beli satu gratis satu minuman segar!”","“Gunakan sabun X agar kulit terasa lebih lembut!”","“Dapatkan sepatu SportMax dengan harga spesial!”","“Ayo hemat air untuk menjaga kelangsungan hidup bersama!”"],"a":3},{"q":"Kalimat persuasif adalah kalimat yang bertujuan untuk ....","o":["menceritakan suatu kejadian","menggambarkan suatu tempat","mengajak atau membujuk seseorang melakukan sesuatu","menjelaskan urutan suatu kegiatan"],"a":2},{"q":"Perhatikan kalimat berikut!\n“Ayo, gunakan tas belanja yang dapat digunakan kembali!”\nKata yang menunjukkan unsur persuasif adalah ....","o":["gunakan","tas","belanja","kembali"],"a":0},{"q":"Kalimat berikut yang paling bersifat persuasif adalah ....","o":["Produk ini dibuat pada tahun 2025.","Produk ini tersedia dalam tiga ukuran.","Ayo, pilih produk berkualitas untuk kebutuhanmu!","Produk ini memiliki berat 500 gram."],"a":2},{"q":"Perhatikan iklan berikut!\n“Tubuh sehat dimulai dari kebiasaan baik. Konsumsilah buah dan sayur setiap hari. Ayo, hidup sehat mulai sekarang!”\nKalimat persuasif dalam iklan tersebut adalah ....","o":["Tubuh sehat dimulai dari kebiasaan baik.","Konsumsilah buah dan sayur setiap hari.","Buah dan sayur mengandung banyak vitamin.","Buah dan sayur tersedia di pasar."],"a":1},{"q":"Penggunaan kata seperti ayo, mari, yuk, segera, pilihlah, gunakanlah dalam iklan bertujuan untuk ....","o":["memberikan penjelasan ilmiah","memperpanjang isi iklan","memengaruhi dan mendorong pembaca melakukan sesuatu","menceritakan pengalaman pembuat iklan"],"a":2},{"q":"Kalimat imperatif adalah kalimat yang digunakan untuk ....","o":["memberikan perintah, larangan, ajakan, atau permintaan","menceritakan suatu kejadian","menjelaskan ciri suatu benda","menyampaikan berita"],"a":0},{"q":"Manakah kalimat berikut yang merupakan kalimat imperatif?","o":["Produk tersebut memiliki rasa manis.","Minuman itu sangat populer di kalangan remaja.","Belilah produk ini sekarang juga!","Produk tersebut dijual di berbagai toko."],"a":2},{"q":"Perhatikan kalimat berikut!\n“Matikan lampu jika tidak digunakan!”\nTujuan penggunaan kalimat imperatif tersebut adalah ....","o":["menceritakan manfaat lampu","memberikan perintah kepada pembaca untuk menghemat energi","menawarkan lampu kepada pembaca","menjelaskan jenis lampu"],"a":1},{"q":"Kalimat berikut yang menggunakan imperatif berupa larangan adalah ....","o":["Ayo, jaga kebersihan sekolah!","Gunakan air secukupnya!","Nikmati makanan sehat setiap hari!","Jangan membuang sampah sembarangan!"],"a":3},{"q":"Mengapa bahasa imperatif sering digunakan dalam iklan?","o":["Agar iklan menjadi seperti cerita","Agar pembaca terdorong melakukan tindakan yang diharapkan pembuat iklan","Agar iklan menjadi lebih panjang","Agar pembaca sulit memahami isi iklan"],"a":1},{"q":"Perhatikan iklan berikut!\nHEMAT LISTRIK, JAGA BUMI!\nMatikan lampu dan peralatan elektronik ketika tidak digunakan. Gunakan listrik seperlunya.\nAyo, mulai hemat energi dari rumah!\nPesan utama iklan tersebut adalah ....","o":["masyarakat harus membeli peralatan elektronik baru","masyarakat diajak menggunakan listrik secara hemat","masyarakat harus menggunakan listrik sebanyak-banyaknya","masyarakat diajak membeli lampu hemat energi"],"a":1},{"q":"Perhatikan iklan berikut!\n“Bawa botol minummu sendiri! Kurangi penggunaan botol plastik sekali pakai. Ayo, mulai kebiasaan ramah lingkungan dari sekarang!”\nPesan utama iklan tersebut adalah ....","o":["mengajak masyarakat membeli botol plastik","mengajak masyarakat mengurangi penggunaan plastik sekali pakai","menawarkan botol minum dengan harga murah","menjelaskan jenis-jenis botol minum"],"a":1},{"q":"Perhatikan iklan berikut!\n“Belajar lebih nyaman dengan MejaBelajar X. Desain praktis, kuat, dan cocok untuk ruang belajar. Dapatkan sekarang di toko terdekat!”\nKesimpulan yang tepat berdasarkan iklan tersebut adalah ....","o":["Iklan mengajak masyarakat menjaga lingkungan.","Iklan memberikan informasi tentang kegiatan sekolah.","Iklan menawarkan meja belajar dan mendorong konsumen untuk membelinya.","Iklan melarang masyarakat membeli meja belajar."],"a":2},{"q":"Perhatikan iklan berikut!\n“Jangan lupa sarapan sebelum beraktivitas! Sarapan membantu menyediakan energi untuk memulai kegiatan. Ayo, biasakan sarapan sehat setiap pagi!”\nPesan utama iklan tersebut adalah ....","o":["mengajak masyarakat tidak makan sebelum beraktivitas","mengajak masyarakat membiasakan sarapan sehat","menawarkan makanan untuk sarapan","menjelaskan jenis makanan yang dijual di pasar"],"a":1},{"q":"Perhatikan iklan berikut!\n“Satu tindakan kecil dapat membuat perubahan besar. Buanglah sampah pada tempatnya dan pilah sampah sesuai jenisnya. Mari bersama-sama menciptakan lingkungan yang bersih dan sehat!”\nSimpulan yang paling tepat adalah ....","o":["Iklan mengajak masyarakat membeli tempat sampah.","Iklan mengajak masyarakat menjaga kebersihan dengan membuang dan memilah sampah dengan benar.","Iklan menjelaskan harga berbagai jenis sampah.","Iklan menawarkan jasa kebersihan lingkungan."],"a":1}],"ads":[{"icon":"👟","title":"Sepatu SportFit","line":"Ringan dan nyaman. Beli sekarang dengan harga spesial!","type":"komersial","reason":"Menawarkan produk sepatu dan mendorong pembelian."},{"icon":"💡","title":"Hemat Energi","line":"Matikan lampu dan alat elektronik saat tidak digunakan.","type":"nonkomersial","reason":"Mengajak masyarakat menghemat energi tanpa menawarkan barang."},{"icon":"🥤","title":"Jus Buah Segar","line":"Nikmati kesegaran jus alami. Pesan hari ini!","type":"komersial","reason":"Menawarkan minuman untuk dijual."},{"icon":"📚","title":"Ayo Membaca!","line":"Luangkan 15 menit setiap hari untuk membaca.","type":"nonkomersial","reason":"Berisi ajakan pendidikan yang bermanfaat bagi masyarakat."},{"icon":"🧼","title":"Sabun Sehat Bersih","line":"Kulit terasa segar setiap hari. Dapatkan sekarang!","type":"komersial","reason":"Mempromosikan sabun agar dibeli."},{"icon":"🌿","title":"Kurangi Plastik","line":"Bawalah tas belanja sendiri untuk menjaga lingkungan.","type":"nonkomersial","reason":"Mengajak menjaga lingkungan tanpa tujuan utama mencari keuntungan."},{"icon":"🚲","title":"Sepeda Kota Baru","line":"Nyaman untuk perjalananmu. Pesan di toko kami!","type":"komersial","reason":"Menawarkan barang dan mengajak konsumen memesannya."},{"icon":"🚰","title":"Gunakan Air Secukupnya","line":"Tutup keran setelah selesai dan jaga sumber air.","type":"nonkomersial","reason":"Berisi imbauan sosial untuk menghemat air."},{"icon":"🍞","title":"Roti Pagi","line":"Lembut, hangat, dan lezat. Beli dua lebih hemat!","type":"komersial","reason":"Mempromosikan makanan untuk memperoleh penjualan."},{"icon":"🗑️","title":"Jaga Kebersihan","line":"Buanglah sampah pada tempatnya!","type":"nonkomersial","reason":"Mengajak masyarakat menjaga kebersihan."},{"icon":"📣","title":"Pesan iklan","line":"Nikmati kesegaran Teh Segar dengan rasa yang nikmat dan menyegarkan!","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"📰","title":"Pesan iklan","line":"Gunakan Sabun Bersih untuk kulit bersih dan wangi sepanjang hari.","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"🔎","title":"Pesan iklan","line":"Belanja sekarang dan dapatkan diskon hingga 50% hanya hari ini!","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"💬","title":"Pesan iklan","line":"Coba Mie Lezat, mi instan gurih dengan rasa yang bikin ketagihan.","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"⭐","title":"Pesan iklan","line":"Sepatu Sporty, nyaman dipakai berolahraga dan cocok untuk aktivitas sehari-hari.","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"🎨","title":"Pesan iklan","line":"Segarkan harimu dengan Jus Buah Segar, dibuat dari buah pilihan.","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"📣","title":"Pesan iklan","line":"Dapatkan smartphone terbaru dengan harga spesial hanya di toko kami!","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"📰","title":"Pesan iklan","line":"Roti Manis Bakery, lembut, lezat, dan cocok untuk teman sarapan.","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"🔎","title":"Pesan iklan","line":"Rawat rambutmu dengan Shampoo Cantik agar rambut tetap lembut dan berkilau.","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"💬","title":"Pesan iklan","line":"Pesan sekarang dan nikmati promo gratis ongkir untuk semua produk!","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"⭐","title":"Pesan iklan","line":"Nikmati kesegaran Teh Pucuk untuk menemani aktivitasmu setiap hari!","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"🎨","title":"Pesan iklan","line":"Gunakan Sabun Lifebuoy agar tubuh tetap bersih dan terlindungi.","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"📣","title":"Pesan iklan","line":"Indomie, mi lezat yang cocok dinikmati kapan saja.","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"📰","title":"Pesan iklan","line":"Segarkan harimu dengan Aqua, air mineral berkualitas untuk kebutuhan sehari-hari.","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"🔎","title":"Pesan iklan","line":"Pepsodent membantu menjaga gigi tetap bersih dan sehat.","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"💬","title":"Pesan iklan","line":"Cuci pakaian dengan Rinso agar bersih dan harum lebih lama.","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"⭐","title":"Pesan iklan","line":"Nikmati kelezatan Oreo, biskuit favorit untuk menemani waktu santai.","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"🎨","title":"Pesan iklan","line":"Gunakan Sunlight untuk membersihkan piring dengan mudah dan cepat.","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"📣","title":"Pesan iklan","line":"Minumlah Susu Ultra Milk untuk melengkapi kebutuhan nutrisi setiap hari.","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"📰","title":"Pesan iklan","line":"Good Day hadir dengan rasa kopi yang nikmat untuk menemani harimu.","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"🔎","title":"Pesan iklan","line":"Dapatkan sepatu berkualitas dengan harga spesial hanya minggu ini!","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"💬","title":"Pesan iklan","line":"Belanja sekarang dan nikmati diskon hingga 50% untuk produk pilihan.","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"⭐","title":"Pesan iklan","line":"Pesan makanan favoritmu sekarang dan dapatkan gratis ongkir!","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"🎨","title":"Pesan iklan","line":"Gunakan Shampoo Fresh untuk rambut bersih, lembut, dan wangi.","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"📣","title":"Pesan iklan","line":"Nikmati camilan renyah dan lezat yang cocok untuk menemani waktu santaimu.","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"📰","title":"Pesan iklan","line":"Beli satu produk dan dapatkan promo menarik khusus hari ini!","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"🔎","title":"Pesan iklan","line":"Hadirkan suasana nyaman di rumah dengan produk berkualitas dari toko kami.","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"💬","title":"Pesan iklan","line":"Temukan pakaian modis dengan harga terjangkau hanya di toko kami.","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"⭐","title":"Pesan iklan","line":"Nikmati minuman segar dengan rasa buah yang lezat setiap hari.","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"🎨","title":"Pesan iklan","line":"Belanja lebih hemat dengan berbagai promo menarik yang tersedia sekarang!","type":"komersial","reason":"Menawarkan barang atau jasa kepada pembaca."},{"icon":"📣","title":"Pesan iklan","line":"Buanglah sampah pada tempatnya untuk menjaga lingkungan tetap bersih.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"📰","title":"Pesan iklan","line":"Ayo hemat air demi menjaga ketersediaan air untuk masa depan.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"🔎","title":"Pesan iklan","line":"Matikan lampu jika tidak digunakan untuk menghemat energi.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"💬","title":"Pesan iklan","line":"Mari biasakan mencuci tangan dengan sabun agar terhindar dari kuman.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"⭐","title":"Pesan iklan","line":"Gunakan masker saat sedang sakit untuk melindungi orang-orang di sekitar kita.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"🎨","title":"Pesan iklan","line":"Ayo membaca setiap hari untuk menambah pengetahuan dan wawasan.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"📣","title":"Pesan iklan","line":"Jangan merokok karena merokok dapat membahayakan kesehatan diri dan orang lain.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"📰","title":"Pesan iklan","line":"Mari tanam pohon untuk menciptakan lingkungan yang lebih hijau dan sehat.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"🔎","title":"Pesan iklan","line":"Stop bullying! Jadilah teman yang saling menghargai dan menyayangi.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"💬","title":"Pesan iklan","line":"Ayo tertib berlalu lintas demi keselamatan diri sendiri dan pengguna jalan lainnya.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"⭐","title":"Pesan iklan","line":"Ayo buang sampah pada tempatnya agar lingkungan tetap bersih.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"🎨","title":"Pesan iklan","line":"Mari hemat air untuk menjaga ketersediaan air bagi generasi mendatang.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"📣","title":"Pesan iklan","line":"Matikan lampu dan peralatan elektronik jika tidak digunakan.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"📰","title":"Pesan iklan","line":"Ayo tanam pohon untuk menciptakan lingkungan yang lebih hijau.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"🔎","title":"Pesan iklan","line":"Jangan merokok karena asap rokok dapat membahayakan kesehatan.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"💬","title":"Pesan iklan","line":"Mari biasakan mencuci tangan dengan sabun untuk menjaga kebersihan.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"⭐","title":"Pesan iklan","line":"Stop bullying! Mari saling menghargai dan menyayangi sesama.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"🎨","title":"Pesan iklan","line":"Gunakan helm saat berkendara demi keselamatan di jalan.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"📣","title":"Pesan iklan","line":"Ayo tertib berlalu lintas untuk menciptakan perjalanan yang aman.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"📰","title":"Pesan iklan","line":"Mari kurangi penggunaan plastik demi menjaga kelestarian lingkungan.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"🔎","title":"Pesan iklan","line":"Jangan membuang sampah ke sungai agar sungai tetap bersih dan sehat.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"💬","title":"Pesan iklan","line":"Ayo rajin membaca untuk menambah ilmu dan wawasan.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"⭐","title":"Pesan iklan","line":"Mari jaga kebersihan sekolah agar kegiatan belajar menjadi nyaman","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"🎨","title":"Pesan iklan","line":"Gunakan air secukupnya dan jangan membiarkannya terbuang sia-sia.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"📣","title":"Pesan iklan","line":"Ayo olahraga secara teratur untuk menjaga tubuh tetap sehat.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"📰","title":"Pesan iklan","line":"Lindungi hewan dan tumbuhan agar keanekaragaman alam tetap terjaga.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"🔎","title":"Pesan iklan","line":"Mari saling membantu dan peduli kepada orang-orang di sekitar kita.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"💬","title":"Pesan iklan","line":"Ayo gunakan transportasi umum untuk membantu mengurangi polusi udara.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"⭐","title":"Pesan iklan","line":"Jangan membakar sampah sembarangan karena dapat mencemari udara.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."},{"icon":"🎨","title":"Pesan iklan","line":"Mari wujudkan lingkungan yang aman, sehat, bersih, dan nyaman bersama-sama.","type":"nonkomersial","reason":"Berisi ajakan atau imbauan yang bermanfaat bagi masyarakat."}],"puzzles":[{"title":"Hemat Energi","image":"poster.svg","type":"nonkomersial","aim":"Mengajak masyarakat menghemat energi","wrongAim":"Menjual lampu","thirdQuestion":"Kalimat imperatif pada poster adalah …","thirdCorrect":"Matikan lampu saat tidak digunakan.","thirdWrong":"Bumi berwarna hijau.","reason":"mengajak masyarakat menghemat energi tanpa menawarkan barang","thirdExplanation":"Ajakan mematikan lampu termasuk kalimat imperatif."},{"title":"Ultra Milk","image":"poster-ultra-milk.jpeg","type":"komersial","aim":"Menawarkan susu untuk dipesan","wrongAim":"Mengajak masyarakat menghemat air","thirdQuestion":"Bagian yang mengajak pembaca memesan adalah …","thirdCorrect":"Order di susunusantara.id yuk!","thirdWrong":"Susu sapi segar","reason":"menawarkan produk susu dan menyediakan cara pemesanan","thirdExplanation":"Ajakan memesan menunjukkan tujuan penjualan."},{"title":"Promo Vaksinasi","image":"poster-vaksinasi.jpeg","type":"komersial","aim":"Menawarkan layanan vaksinasi dengan harga spesial","wrongAim":"Mengajak masyarakat membaca","thirdQuestion":"Bagian mana yang menunjukkan penawaran jasa?","thirdCorrect":"Harga spesial vaksinasi hepatitis","thirdWrong":"Gambar organ hati","reason":"menampilkan harga untuk layanan vaksinasi","thirdExplanation":"Harga spesial menunjukkan layanan yang ditawarkan."},{"title":"Hemat Air","image":"poster-hemat-air.jpeg","type":"nonkomersial","aim":"Mengajak masyarakat menghemat air","wrongAim":"Menjual keran air","thirdQuestion":"Kalimat imbauan pada poster adalah …","thirdCorrect":"Hematlah air","thirdWrong":"Harga keran murah","reason":"mengajak masyarakat menjaga ketersediaan air tanpa penjualan","thirdExplanation":"“Hematlah air” adalah imbauan kepada masyarakat."},{"title":"Roti Ceria","image":"poster-roti.svg","type":"komersial","aim":"Menawarkan roti dengan promo pembelian","wrongAim":"Mengajak masyarakat menghemat listrik","thirdQuestion":"Kalimat yang menunjukkan penawaran pada poster adalah …","thirdCorrect":"Beli 2, gratis 1!","thirdWrong":"Hangat, lembut, bikin semangat.","reason":"menawarkan produk roti dengan promo dan ajakan membeli","thirdExplanation":"“Beli 2, gratis 1!” adalah penawaran untuk menarik pembeli."}],"materials":[{"title":"Apa itu iklan?","body":"Pengertian iklan\n\nIklan adalah pesan atau informasi yang dibuat untuk memperkenalkan, menawarkan, atau mengajak masyarakat menggunakan produk, jasa, atau mengikuti kegiatan.\n\nIklan dapat ditemukan di televisi, radio, surat kabar, majalah, poster, brosur, spanduk, internet, media sosial, dan aplikasi digital.\n\n“Ayo, gunakan botol minum ramah lingkungan! Praktis, tahan lama, dan membantu mengurangi sampah plastik.”\n\nContoh ini memberi informasi sekaligus mengajak pembaca menggunakan produk tertentu.","image":""},{"title":"Ciri-ciri iklan","body":"Enam ciri utama\n\nInformatif: menjelaskan produk, jasa, kegiatan, atau layanan.\n\nPersuasif: membujuk pembaca melakukan sesuatu.\n\nSingkat dan jelas: mudah dibaca serta dipahami.\n\nKata-kata menarik: membuat pembaca tertarik.\n\nMemiliki sasaran: ditujukan kepada kelompok tertentu.\n\nDaya tarik visual atau audio: memakai gambar, warna, huruf, musik, suara, atau video.","image":""},{"title":"Tujuan iklan","body":"Mengapa iklan dibuat?\n\nMemberi informasi tentang produk, jasa, kegiatan, atau program.\n\nMembujuk masyarakat agar tertarik membeli atau menggunakan sesuatu.\n\nMengingatkan masyarakat tentang produk atau kebiasaan tertentu.\n\nMengajak melakukan tindakan yang bermanfaat.","image":""},{"title":"Jenis iklan","body":"Komersial atau nonkomersial?\n\nKomersialMenawarkan barang atau jasa untuk memperoleh keuntungan. Contoh: makanan, pakaian, kendaraan.\n\nNonkomersialMemberi informasi, edukasi, atau ajakan sosial. Contoh: hemat energi, menjaga kebersihan.\n\nLihat tujuan utama iklan. Jika mengajak membeli, biasanya komersial. Jika mengajak melakukan hal bermanfaat bagi masyarakat tanpa penjualan, biasanya nonkomersial.","image":""},{"title":"Kalimat imperatif","body":"Ajakan dan perintah\n\nKalimat imperatif digunakan untuk memerintah, meminta, melarang, atau mengajak seseorang melakukan sesuatu.\n\nKata yang sering muncul: ayo, gunakan, jangan, belilah, jagalah.\n\n“Gunakan air secukupnya!”\n\n“Jangan membuang sampah sembarangan!”","image":""},{"title":"Kalimat persuasif","body":"Bujukan yang meyakinkan\n\nKalimat persuasif membujuk, meyakinkan, atau memengaruhi pembaca. Kalimat ini sering menyebut alasan, manfaat, atau keunggulan.\n\n“Bacalah buku setiap hari agar pengetahuanmu bertambah!”\n\nAlasan “agar pengetahuanmu bertambah” membuat ajakan itu lebih meyakinkan.","image":""},{"title":"Bedakan keduanya","body":"Imperatif dan persuasif\n\nImperatifMenekankan perintah, larangan, permintaan, atau ajakan.\n\nPersuasifMenekankan alasan dan manfaat agar pembaca tertarik.\n\n“Gunakan produk ini!” → imperatif.\n\n“Gunakan produk ini untuk mendapatkan manfaat yang lebih baik.” → persuasif.\n\nKeduanya bisa muncul bersama dalam satu iklan.","image":""}],"essays":[]}'::jsonb) returning id into version_id;
    insert into public.learning_current(id,revision) values(1,version_id);
  end if;
end $seed$;
notify pgrst, 'reload schema';
commit;
